SELECT order_id,merchant_id,carrier,tracking_number,posted_at IS NOT NULL AS posted,warehouse_id,
  warehouse_receipt_at IS NOT NULL AS received,voided_at IS NOT NULL AS voided
FROM order_package_allocations WHERE package_id=#{packageId}

SELECT EXISTS (
  SELECT 1 FROM order_package_allocations WHERE order_id=#{orderId}
    AND carrier=#{carrier} AND tracking_number=#{trackingNumber} AND voided_at IS NULL
)

SELECT COALESCE(SUM(COALESCE(l.actual_quantity,l.quantity)),0) FROM order_package_lines l
JOIN order_package_allocations p ON p.package_id=l.package_id
WHERE l.order_line_id=#{orderLineId} AND p.warehouse_id=#{warehouseId}
